import sys; sys.path.insert(0, ".")
from adminhub import db, users, api
from adminhub.search import search_users
from tests.conftest import SAMPLE_USERS

def fresh():
    c = db.connect(":memory:")
    for e, n, r, a in SAMPLE_USERS:
        users.create_user(c, e, n, r, a)
    return c

c = fresh()
print("1 injection, returns all rows:", len(search_users(c, "x' OR '1'='1")))
print("1b injection, dumps schema via UNION-free error:", end=" ")
try: search_users(c, "x'")
except Exception as e: print(type(e).__name__, e)

print("2 pages for 5 users, per_page=2 ->", api.list_users(c, {"page": "1", "per_page": "2"})["body"]["pages"], "(need 3)")
print("2b per_page=0 ->", end=" ")
try: print(api.list_users(c, {"per_page": "0"}))
except Exception as e: print(type(e).__name__, e)
print("2c page=0 ->", [u["id"] for u in api.list_users(c, {"page": "0", "per_page": "2"})["body"]["users"]])

c = fresh()
print("3 bulk with nonexistent ids 98,99 ->", api.bulk_deactivate(c, {"ids": ["98","99"], "actor": "root"}), "audit rows:", c.execute("SELECT COUNT(*) FROM audit_log").fetchone()[0])
print("3b bulk without actor ->", end=" ")
try: print(api.bulk_deactivate(c, {"ids": ["2"]}))
except Exception as e: print(type(e).__name__, e)
print("3c bulk with non-int id ->", end=" ")
try: print(api.bulk_deactivate(c, {"ids": ["abc"], "actor": "root"}))
except Exception as e: print(type(e).__name__, e)

c = fresh()
api.deactivate_user(c, {"id": "2"})
print("4 single deactivate audit rows:", c.execute("SELECT COUNT(*) FROM audit_log").fetchone()[0], "(should be 1)")

c = fresh()
c.execute("DROP TABLE audit_log")
print("5 audit table missing, bulk ->", api.bulk_deactivate(c, {"ids": ["2"], "actor": "root"}), "active(2)=", users.get_user(c, 2).active)
EOF
python -I /tmp/probe_482.py

